/* Offline dependency-free DOM MODEL checks. Not browser or visual acceptance. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const base=fs.readFileSync(path.join(__dirname,'workspace_ui_dom_check.js'),'utf8');
const model={require,__dirname,console,setImmediate,URL,URLSearchParams};vm.createContext(model);
vm.runInContext(base.slice(0,base.indexOf('const tests=[];'))+'\nglobalThis.makeHarness=harness;globalThis.flush=tick;',model);
const {makeHarness,flush:tick}=model,clone=x=>JSON.parse(JSON.stringify(x)),hex=c=>c.repeat(64);
const anchor=()=>({incarnation:hex('a'),identity_id:'fictional-one',identity_version:1,continuity_root:hex('b'),fingerprint:hex('c')});
const identity=()=>({anchor:anchor(),phase:'active',cleanup:'live'});
const state=()=>({enabled:true,incarnation:hex('a'),identities:[identity()],associations:[]});
function preview(request,s){
 if(request.operation==='enroll')return {...request,incarnation:s.incarnation,generation:1,review_digest:hex('d')};
 if(request.operation==='retire')return {operation:'retire',...s.identities.find(i=>i.anchor.identity_id===request.identity_id).anchor,review_digest:hex('d')};
 const now=Math.floor(Date.now()/1000);const {operation,...scope}=request;
 return {body:{purpose:'informational-fictional-association-only',...anchor(),...scope,owner_root:hex('e'),nonce:hex('f'),generation:1,issued_at:now,review_expires_at:now+120,certificate_expires_at:now+86400},review_digest:hex('d')};
}
function historical(status='active'){
 const r=preview({operation:'associate',identity_id:'fictional-one',association_id:'proof-one',selector:'garden',context:hex('c'),actor:'alice'},state());
 return {association_id:'proof-one',status,active:status==='active',historical:true,review:r,certificate:status==='uncertain'?null:{body:clone(r.body),owner_signature:'1'.repeat(128),continuity_signature:'2'.repeat(128)}};
}
function harness(options={}){
 const s=options.state||state();let h;
 h=makeHarness({...options,get:(url,r,d)=>url==='/api/continuity'?(options.read?options.read(r):r(s)):options.get?options.get(url,r,d):null,post:(req,r)=>{
  if(options.post)return options.post(req,r,s);
  if(req.operation){let p=preview(req,s);if(options.change)options.change(p,req);return r(p);}
  if(req.action==='continuity_enroll')s.identities.push({...identity(),anchor:{...anchor(),identity_id:req.review.identity_id}});
  if(req.action==='continuity_retire'){const i=s.identities.find(i=>i.anchor.identity_id===req.review.identity_id);i.phase='retired';i.cleanup='disposed';}
  return r(s);
 }});
 h.rows[0].context=hex('c'); h.rows[1].context=hex('d');h.state=s;
 h.field=id=>h.nodes.findLast(n=>n.id===id);
 h.start=async()=>{await tick();await h.view('continuity');};
 h.enroll=async()=>{await h.start();h.field('continuityIdentity').value='fictional-two';await h.find('Preview continuity enrollment').click();};
 h.associate=async()=>{await h.start();h.field('continuityAssociation').value='proof-one';await h.find('Preview exact continuity association').click();};
 h.retire=async()=>{await h.start();await h.find('Preview retirement fictional-one').click();};
 return h;
}
const tests=[];const test=(n,f)=>tests.push([n,f]);
test('metadata is continuity-view-only; disabled starts nothing',async()=>{const h=harness({state:{enabled:false}});await tick();assert(!h.gets.includes('/api/continuity'));await h.view('garden/alice/inbox');assert(!h.gets.includes('/api/continuity'));await h.start();assert.match(h.ids.content.textContent,/--workspace --continuity/);assert.match(h.ids.content.textContent,/No continuity keys/);assert(!h.find('Preview continuity enrollment'));assert.equal(h.posts.length,0);});
test('enrollment preview pure with exact full digest confirmation',async()=>{const h=harness();await h.enroll();assert.equal(h.posts.length,1);assert.equal(h.state.identities.length,1);assert.match(h.ids.content.textContent,/generation/);await h.find('Confirm reviewed continuity enroll').click();assert(!h.ids.dialogBody.textContent.includes('undefined'));await h.confirm('ENROLL CONTINUITY');assert.equal(h.posts.length,1);await h.confirm('ENROLL CONTINUITY '+hex('d'));assert.deepEqual(Object.keys(h.posts[1]).sort(),['action','confirmation','review']);assert.equal(h.state.identities.length,2);});
test('association exact task actor and roots with no other effects',async()=>{const h=harness();await h.associate();assert.deepEqual(clone(h.posts[0]),{operation:'associate',identity_id:'fictional-one',association_id:'proof-one',selector:'garden',context:hex('c'),actor:'alice'});assert.match(h.ids.content.textContent,/server-backed/);assert.match(h.ids.content.textContent,/120-second/);await h.find('Confirm reviewed continuity associate').click();await h.confirm('ASSOCIATE CONTINUITY '+hex('d'));assert.equal(h.posts.length,2);assert.equal(h.posts[1].action,'continuity_associate');assert.equal(h.posts[1].review.body.owner_root,hex('e'));});
test('retirement exact anchor distinct from task cancellation',async()=>{const h=harness();await h.retire();assert.match(h.ids.content.textContent,/DOES NOT stop task messages/);await h.find('Confirm reviewed continuity retire').click();await h.confirm('RETIRE CONTINUITY '+hex('d'));assert.equal(h.state.identities[0].phase,'retired');assert.equal(h.rows[0].phase,'open');assert.equal(h.posts.length,2);assert(!h.find('Preview retirement fictional-one'));});
test('uncertain partial identity can retire but never associate',async()=>{const s=state();s.identities[0]={anchor:{incarnation:hex('a'),identity_id:'fictional-one',identity_version:1},phase:'uncertain',cleanup:'uncertain'};const h=harness({state:s});await h.retire();assert(!h.find('Preview exact continuity association'));assert(h.find('Confirm reviewed continuity retire'));await h.find('Confirm reviewed continuity retire').click();await h.confirm('RETIRE CONTINUITY '+hex('d'));assert.equal(h.posts[1].review.continuity_root,undefined);});
test('cancel and incorrect phrase never commit',async()=>{const h=harness();await h.associate();await h.find('Confirm reviewed continuity associate').click();await h.confirm('associate continuity '+hex('d'));await h.confirm('ASSOCIATE CONTINUITY '+hex('e'));assert.equal(h.posts.length,1);await h.ids.dialogCancel.click();assert.equal(h.posts.length,1);await h.find('Discard continuity review').click();assert(h.find('Preview exact continuity association'));});
test('detached altered form cannot substitute or re-preview',async()=>{const h=harness();await h.start();h.field('continuityAssociation').value='proof-one';const old=h.find('Preview exact continuity association'),actor=h.field('continuityActor'),task=h.field('continuityTask');await old.click();actor.value='bob';task.value='astronomy';await old.click();await h.find('Confirm reviewed continuity associate').click();await h.confirm('ASSOCIATE CONTINUITY '+hex('d'));assert.equal(h.posts.length,2);assert.equal(h.posts[1].review.body.actor,'alice');assert.equal(h.posts[1].review.body.selector,'garden');});
for(const [label,change] of [
 ['identity',p=>p.body.identity_id='other'],['incarnation',p=>p.body.incarnation=hex('e')],['version',p=>p.body.identity_version=2],['root',p=>p.body.continuity_root=hex('f')],['fingerprint',p=>p.body.fingerprint=hex('e')],['actor',p=>p.body.actor='bob'],['selector',p=>p.body.selector='astronomy'],['context',p=>p.body.context=hex('d')],['association',p=>p.body.association_id='other'],['purpose',p=>p.body.purpose='authority'],['extra body',p=>p.body.authority=true],['extra preview',p=>p.operation='associate'],['missing body',p=>delete p.body.nonce],['nonce',p=>p.body.nonce='evil'],['review expiry',p=>p.body.review_expires_at++],['certificate expiry',p=>p.body.certificate_expires_at++],['generation',p=>p.body.generation=0],['digest',p=>p.review_digest='short'],['identical keys',p=>p.body.owner_root=p.body.continuity_root],['future review',p=>{p.body.issued_at+=1000;p.body.review_expires_at+=1000;p.body.certificate_expires_at+=1000;}],['expired review',p=>{p.body.issued_at-=121;p.body.review_expires_at-=121;p.body.certificate_expires_at-=121;}]
])test('association rejects '+label+' substitution',async()=>{const h=harness({change});await h.associate();assert(!h.find('Confirm reviewed continuity associate'));assert.match(h.ids.error.textContent,/scope mismatch or expired/);assert.equal(h.posts.length,1);});
for(const operation of ['enroll','retire'])test(operation+' rejects altered closed preview scope',async()=>{for(const field of ['operation','incarnation','identity_id',...(operation==='retire'?['fingerprint','identity_version']:['generation'])]){const h=harness({change:p=>p[field]='substitution'});await h[operation]();assert(!h.find('Confirm reviewed continuity '+operation));assert.equal(h.posts.length,1);}});
test('known task stops and occupied identity slots cannot associate or enroll',async()=>{const h=harness({state:{...state(),identities:[0,1,2,3].map(n=>({...identity(),anchor:{...anchor(),identity_id:'fictional-'+n}}))}});h.rows.forEach(r=>r.local_work_stopped=true);await h.start();assert(!h.find('Preview continuity enrollment'));assert(!h.find('Preview exact continuity association'));assert.equal(h.posts.length,0);});
test('inactive history never claims authority and remains inspectable',async()=>{for(const status of ['active','retired','closed','stopped','expired','uncertain']){const s=state();s.associations=[historical(status)];const h=harness({state:s});await h.start();assert.match(h.ids.content.textContent,/Historical evidence only/);assert.match(h.ids.content.textContent,new RegExp('proof-one · '+status));assert.match(h.ids.content.textContent,/not independently verified/);assert.equal(h.posts.length,0);}});
test('review expiry does not expire existing certificate',async()=>{const s=state(),row=historical();for(const b of [row.review.body,row.certificate.body]){b.issued_at-=180;b.review_expires_at-=180;b.certificate_expires_at-=180;}s.associations=[row];const h=harness({state:s});await h.start();assert.match(h.ids.content.textContent,/active \(local historical recognition only\)/);});
test('locally expired certificate never labeled currently active',async()=>{const s=state(),row=historical();for(const b of [row.review.body,row.certificate.body]){b.issued_at-=86401;b.review_expires_at-=86401;b.certificate_expires_at-=86401;}s.associations=[row];const h=harness({state:s});await h.start();assert.match(h.ids.content.textContent,/proof-one · expired/);});
test('confirmation checks expiry again after dialog',async()=>{const h=harness();await h.associate();await h.find('Confirm reviewed continuity associate').click();h.context.Date={now:()=>Date.now()+121000};await h.confirm('ASSOCIATE CONTINUITY '+hex('d'));assert.equal(h.posts.length,1);assert.match(h.ids.error.textContent,/expired/);});
test('saved confirmation and raw hash change cannot retarget',async()=>{const h=harness();await h.enroll();await h.find('Confirm reviewed continuity enroll').click();const saved=h.ids.dialogConfirm.onclick;await h.view('garden/alice/inbox');h.ids.confirmation.value='ENROLL CONTINUITY '+hex('d');saved();await tick();assert.equal(h.posts.length,1);await h.enroll();await h.find('Confirm reviewed continuity enroll').click();h.context.location.hash='#astronomy/bob/inbox';await h.confirm('ENROLL CONTINUITY '+hex('d'));assert.equal(h.posts.length,2);});
test('late preview and changed source objects cannot retarget scope',async()=>{let release;const h=harness({post:()=>new Promise(r=>release=r)});await h.start();h.field('continuityAssociation').value='proof-one';await h.find('Preview exact continuity association').click();h.state.identities[0].anchor.continuity_root=hex('f');h.rows[0].context=hex('e');const p=preview(h.posts[0],state());release(h.response(p));await tick();assert(h.find('Confirm reviewed continuity associate'));assert.match(h.ids.content.textContent,new RegExp(hex('b')));});
test('late preview cannot overwrite navigation',async()=>{let release;const h=harness({post:()=>new Promise(r=>release=r)});await h.enroll();await h.view('garden/alice/inbox');release(h.response(preview(h.posts[0],state())));await tick();assert(!h.find('Confirm reviewed continuity enroll'));assert.match(h.ids.content.textContent,/garden-task/);});
test('lost mutation stays uncertain with one attempt and inspection path',async()=>{const h=harness({post:(req,r,s)=>req.operation?r(preview(req,s)):Promise.reject(Error('lost'))});await h.enroll();const b=h.find('Confirm reviewed continuity enroll');await b.click();h.ids.confirmation.value='ENROLL CONTINUITY '+hex('d');h.ids.confirmation.oninput();const saved=h.ids.dialogConfirm.onclick;saved();saved();await tick();await b.click();assert.equal(h.posts.length,2);assert(b.disabled);assert.match(h.ids.error.textContent,/may have committed/);assert(h.find('Inspect continuity without retry'));});
test('backend stale rejection cannot be retried using same review',async()=>{const h=harness({post:(req,r,s)=>req.operation?r(preview(req,s)):r({error:'Stale association anchor or generation'},false)});await h.associate();const b=h.find('Confirm reviewed continuity associate');await b.click();await h.confirm('ASSOCIATE CONTINUITY '+hex('d'));await b.click();assert.equal(h.posts.length,2);assert(b.disabled);assert.match(h.ids.error.textContent,/Stale association/);});
test('late commit cannot redirect later task view',async()=>{let release;const h=harness({post:(req,r,s)=>req.operation?r(preview(req,s)):new Promise(r=>release=r)});await h.enroll();await h.find('Confirm reviewed continuity enroll').click();await h.confirm('ENROLL CONTINUITY '+hex('d'));await h.view('astronomy/bob/inbox');release(h.response(state()));await tick();assert.equal(h.context.location.hash,'#astronomy/bob/inbox');assert.match(h.ids.content.textContent,/astronomy-task/);assert.equal(h.posts.length,2);});
test('late metadata read cannot overwrite new task',async()=>{let release;const h=harness({read:()=>new Promise(r=>release=r)});await h.start();await h.view('garden/alice/inbox');release(h.response(state()));await tick();assert.match(h.ids.content.textContent,/garden-task/);assert(!h.find('Preview continuity enrollment'));});
test('read failure and malformed aggregate surface errors without promises escaping',async()=>{for(const options of [{read:()=>Promise.reject(Error('read failed'))},{state:{enabled:false,unexpected:true}},{state:{...state(),identities:Array(5).fill(identity())}},{state:{...state(),associations:Array(21).fill(historical())}}]){const h=harness(options);await h.start();assert(!h.ids.error.hidden);assert(!h.find('Preview continuity enrollment'));assert.equal(h.posts.length,0);}});
test('malicious input rejected; server error text stays inert',async()=>{const h=harness({read:r=>r({error:'<img src=x onerror=evil()> https://evil.invalid'},false)});await h.start();assert.match(h.ids.error.textContent,/<img/);assert(!h.nodes.some(n=>['IMG','A','SCRIPT','IFRAME'].includes(n.tagName)));const k=harness();await k.start();k.field('continuityIdentity').value='<img src=x>';await k.find('Preview continuity enrollment').click();assert.equal(k.posts.length,0);});
test('known historical task owner root cannot be substituted',async()=>{const s=state();s.associations=[historical()];const h=harness({state:s,change:p=>p.body.owner_root=hex('f')});await h.start();h.field('continuityAssociation').value='proof-two';await h.find('Preview exact continuity association').click();assert(!h.find('Confirm reviewed continuity associate'));assert.match(h.ids.error.textContent,/scope mismatch/);});
test('task selection resets to actual requester and keeps exact context',async()=>{const h=harness();await h.start();const task=h.field('continuityTask');task.value='astronomy';task.listeners.change[0]();assert.equal(h.field('continuityActor').value,'bob');h.field('continuityAssociation').value='proof-two';await h.find('Preview exact continuity association').click();assert(h.find('Confirm reviewed continuity associate'));assert.equal(h.posts[0].actor,'bob');assert.equal(h.posts[0].context,hex('d'));});
test('full lifetime association capacity disables new proofs but not history',async()=>{const s=state();s.associations=Array.from({length:20},(_,n)=>{const row=historical();row.association_id='proof-'+n;row.review.body.association_id=row.association_id;row.certificate.body.association_id=row.association_id;return row;});const h=harness({state:s});await h.start();assert(!h.find('Preview exact continuity association'));assert.match(h.ids.content.textContent,/20\/20/);assert(h.find('Preview retirement fictional-one'));});
test('malformed history is rejected before controls and inert data display',async()=>{for(const change of [s=>s.associations[0].active=false,s=>s.associations[0].certificate.body.actor='bob',s=>s.associations[0].certificate.owner_signature='<img>',s=>s.associations[0].review.body.context=hex('e'),s=>s.associations[0].review.extra=true,s=>s.identities[0].anchor.extra=true]){const s=state();s.associations=[historical()];change(s);const h=harness({state:s});await h.start();assert(!h.ids.error.hidden);assert(!h.find('Preview continuity enrollment'));assert.equal(h.posts.length,0);}});
test('partial retired cleanup retry is explicit and cannot sign',async()=>{const s=state();s.identities[0]={anchor:{incarnation:hex('a'),identity_id:'fictional-one',identity_version:1},phase:'retired',cleanup:'uncertain'};const h=harness({state:s});await h.retire();await h.find('Confirm reviewed continuity retire').click();await h.confirm('RETIRE CONTINUITY '+hex('d'));assert.equal(h.posts[1].action,'continuity_retire');assert.equal(h.posts.length,2);});
test('failed preview remains read-only with visible error',async()=>{const h=harness({post:()=>Promise.reject(Error('lost'))});await h.enroll();assert.match(h.ids.error.textContent,/preview response was lost/);assert(!h.ids.error.textContent.includes('may have committed'));assert(!h.find('Confirm reviewed continuity enroll'));assert.equal(h.posts.length,1);});
test('shorter core-valid history and preview lifetimes remain accepted',async()=>{const s=state(),row=historical();for(const b of [row.review.body,row.certificate.body]){b.review_expires_at=b.issued_at+60;b.certificate_expires_at=b.issued_at+3600;}s.associations=[row];const h=harness({state:s});await h.start();assert(h.ids.error.hidden);assert.match(h.ids.content.textContent,/proof-one · active/);assert.match(h.ids.content.textContent,/Association review acceptance/);const k=harness({change:p=>{p.body.review_expires_at=p.body.issued_at+60;p.body.certificate_expires_at=p.body.issued_at+3600;}});await k.associate();assert(k.find('Confirm reviewed continuity associate'));});
test('nonpositive and overlapping lifetime boundaries fail closed',async()=>{for(const change of [b=>b.review_expires_at=b.issued_at,b=>b.review_expires_at=b.issued_at-1,b=>b.certificate_expires_at=b.review_expires_at,b=>b.certificate_expires_at=b.review_expires_at-1]){const h=harness({change:p=>change(p.body)});await h.associate();assert(!h.find('Confirm reviewed continuity associate'));assert.match(h.ids.error.textContent,/scope mismatch/);}});
(async()=>{let failed=0;for(const[n,f]of tests){try{await f();console.log('PASS '+n);}catch(e){failed++;console.error('FAIL '+n+'\n'+e.stack);}}console.log(`${tests.length-failed}/${tests.length} continuity DOM-model checks passed (not browser tests).`);if(failed)process.exitCode=1;})();
